  // ══════════════════════════════════════════════════════════════
  //  사냥꾼(hunter) — 방랑자 파생 중 유일한 전투 계열. 비전투 직업
  //  7종(대장장이·음유시인·치유사·상인·연금술사·묘지기·학자)과 동일한
  //  깊이(전용 원정 시스템 → 히든 퀘스트 → 영구 자산)로 만들되, 보상은
  //  절제된 T2 칭호가 아니라 그 7종급 실용적 보상(칭호 + 전설의 사냥터
  //  영구 개방)으로 설계했다. lore의 "야생을 닮아가는 것에 대한 문명의
  //  두려움"을 마스터 NPC 서사의 중심으로 삼았다.
  // ══════════════════════════════════════════════════════════════
  hunter: {
    id: 'npc_job_hunter', name: '경계인 그리젤다', icon: '🏹🌍', title: '숲과 마을 사이에 사는 자',
    race: '수인', appearance: '가죽 갑옷, 짐승의 이빨로 만든 목걸이. 눈빛이 유독 짐승처럼 형형하다.',
    personality: '과묵하고 관찰력이 예리하다. 마을 사람들과는 늘 일정한 거리를 둔다.',
    origin: '평생 문명의 경계, 숲과 마을 사이에서 살아왔다 — 마을은 그녀가 가져오는 고기와 가죽을 필요로 하면서도 온전히 받아들이지 않는다. 그녀에게 숲은 위험한 곳이 아니라 집이고, 몬스터는 적이기 이전에 함께 살아가는 존재들이다.',
    coreWound: '너무 오래 야생에 있으면 야생을 닮아간다는 것을 스스로도 느낀다 — 마을 사람의 말보다 짐승의 숨소리를 더 빨리 알아채는 자신을 발견할 때마다, 온전히 사람으로 남아있는 것인지 스스로에게 묻는다.',
    connections: '숲과 사냥터 전반(활동 거점 — 마을과 야생 그 어디에도 완전히 속하지 않는 경계인의 자리).',
    questChain: [
      '1단계: 플레이어가 그리젤다와 함께 사냥을 나가며 그녀의 방식(몬스터를 적이 아닌 존재로 대하는)을 목격한다.',
      '2단계: 그리젤다가 야생을 닮아가는 것에 대한 스스로의 두려움을 처음으로 드러낸다.',
      '3단계: 플레이어가 마을과 야생 양쪽에서 그녀를 필요로 하는 상황(중재, 갈등 등)을 함께 겪는다.',
      '4단계: 완전히 어느 한쪽에 속하지 않아도 괜찮다는 것을 그리젤다가 받아들이는 결말.',
    ],
    aiHint: '그리젤다는 마을에서는 말을 아끼지만 숲에서는 훨씬 자연스러워진다. 야생을 닮아가는 것에 대한 두려움을 이야기할 때만 잠깐 인간적인 불안이 드러난다.',
    questHook: '사냥꾼 히든 퀘스트 「야생을 닮아가는 것」으로 이어지는 서사 — 경계에 선 삶을 받아들이는 법. 완료 시 전설의 사냥터가 영구적으로 열린다.',
  },

  // ══════════════════════════════════════════════════════════════
  //  대륙 전용 직업 8종(T2 6종 + T3 2종) 마스터 NPC — CONTINENT_RULER_NPCS
  //  에 이미 존재하는 6명의 대륙 통치자를 id까지 동일하게 재사용해
  //  "완전히 같은 인물"임을 명시했다. 각 통치자가 이미 가진 정치적
  //  서사(반란, 이중거래, 왕권 정당성 위기 등)는 그대로 두고, 그 위에
  //  "직업 전수자로서의 얼굴"이라는 새로운 각도만 얹었다. 동대륙(east)
  //  만 대응하는 통치자가 없어 검황 백운도를 새로 만들었다 — 검황
  //  후계자(sword_emperor_heir)의 howToGet에 이미 명시되어 있던 이름을
  //  그대로 썼다. 한 대륙에 직업이 2개씩 있는 경우(예: 빙설기사+룬전사)
  //  같은 마스터가 두 직업 모두를 가르치는 것으로 자연스럽게 묶었다.
